INSERT OR REPLACE INTO dishes (id, name, description, image, yt_url, prep_time, cook_time, cuisine, meal_type, category, servings, calories, ingredients, instructions, flavor_profile, variations, created_at) VALUES
('dish-1', 'Aloo parantha', 'A classic Indian flatbread made with whole wheat flour and stuffed with a spiced potato mixture. Perfect for breakfast, lunch, or dinner.', 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop', 'https://www.youtube.com/watch?v=k1tCscN65fM', '20 minutes', '20 minutes', 'Indian', '["Breakfast","Lunch","Dinner"]', 'Vegetarian', 4, 350, '["Potatoes","Wheat flour","Amchur powder","Garam masala","Coriander powder","Cumin powder","Turmeric powder","Salt","Oil","Water"]', '["Boil potatoes until tender, peel, and mash them.","In a bowl, mix mashed potatoes with finely chopped onion, ginger-garlic paste, green chilies, and all spices.","Divide dough into equal portions. Roll each portion into a circle.","Place a portion of potato filling in the center and fold the edges to seal.","Roll gently into a flat, even parantha.","Heat a griddle (tawa) over medium heat. Cook the parantha on both sides until golden brown spots appear.","Serve hot with yogurt, pickle, or butter."]', '["spicy","savory"]', '["Add chopped spinach for a healthier version.","Use paneer or cauliflower instead of potatoes for a different twist."]', '2026-08-13T10:00:00.000Z'),
('dish-2', 'Butter Chicken (Murgh Makhani)', 'Tender chicken pieces simmered in a velvety, rich tomato, butter, and cream sauce infused with aromatic Indian spices.', 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?w=600&auto=format&fit=crop', 'https://www.youtube.com/watch?v=a03U45jFxOI', '30 minutes', '35 minutes', 'Indian', '["Lunch","Dinner"]', 'Non-Vegetarian', 4, 520, '["Chicken thigh chunks","Yogurt","Ginger garlic paste","Butter","Heavy cream","Tomato puree","Kasuri methi","Garam masala","Kashmiri red chili powder","Salt"]', '["Marinate chicken in yogurt and spices for 1 hour.","Sear marinated chicken in a hot pan.","Prepare sauce by simmering tomato puree, butter, and spices.","Add seared chicken pieces and simmer for 15 minutes.","Finish with heavy cream and kasuri methi."]', '["rich","creamy","savory"]', '["Substitute chicken with grilled Paneer."]', '2026-08-13T10:05:00.000Z'),
('dish-3', 'Paneer Tikka Masala', 'Marinated cottage cheese cubes grilled to perfection and tossed in a rich, spiced onion-tomato gravy.', 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=600&auto=format&fit=crop', 'https://www.youtube.com/watch?v=J84qO8k2K_s', '25 minutes', '25 minutes', 'Indian', '["Lunch","Dinner"]', 'Vegetarian', 4, 410, '["Paneer cubes","Bell peppers","Onions","Yogurt","Tomato gravy","Ginger garlic paste","Kasuri methi","Butter","Spices mix"]', '["Marinate paneer, onion, and bell pepper chunks.","Grill on medium heat until slightly charred.","Sauté onions, ginger, garlic, and tomatoes.","Add grilled paneer and simmer in gravy."]', '["spicy","smoky","savory"]', '["Add mushrooms or tofu."]', '2026-08-13T10:10:00.000Z'),
('dish-4', 'Classic Margherita Pizza', 'Traditional Neapolitan pizza topped with fresh tomato sauce, creamy mozzarella, basil leaves, and olive oil.', 'https://images.unsplash.com/photo-1604382354936-07c5d9983bd3?w=600&auto=format&fit=crop', 'https://www.youtube.com/watch?v=1-SJGQ2HLp8', '20 minutes', '15 minutes', 'Italian', '["Lunch","Dinner"]', 'Vegetarian', 3, 480, '["Pizza dough","San Marzano tomatoes","Fresh Mozzarella","Fresh Basil leaves","Extra virgin olive oil","Sea salt"]', '["Stretch pizza dough into a 12-inch disc.","Spread crushed San Marzano tomato sauce.","Place fresh mozzarella slices.","Bake in preheated oven.","Top with fresh basil and olive oil."]', '["savory","tangy","herbaceous"]', '["Add cherry tomatoes or garlic oil."]', '2026-08-13T10:15:00.000Z');
